"use client";

import { animate, motion, useReducedMotion, type Transition } from "motion/react";
import {
  type ComponentPropsWithoutRef,
  type PointerEvent,
  type ReactNode,
  useCallback,
  useEffect,
  useRef,
  useState,
} from "react";

import { cn } from "@/lib/utils";

/** The side a card left on. Right is the positive choice. */
export type SwipeDirection = "left" | "right";

/**
 * Props for a swipe deck. `index` counts the cards already dismissed: pass it
 * to control the deck, or `defaultIndex` to let the deck hold its own place.
 */
export type SwipeDeckProps<T> = Omit<ComponentPropsWithoutRef<"div">, "children"> & {
  /** Names the deck for screen readers, for example "Templates". */
  label: string;
  items: T[];
  getKey: (item: T) => string;
  /** The short name read out when a card comes to the top. */
  getName: (item: T) => string;
  renderCard: (item: T) => ReactNode;
  index?: number;
  defaultIndex?: number;
  onIndexChange?: (index: number) => void;
  /** Fires once per dismissed card, for a drag and for a button alike. */
  onSwipe?: (item: T, direction: SwipeDirection) => void;
  leftLabel?: string;
  rightLabel?: string;
  /** Shown and read out when no card is left. */
  emptyLabel?: string;
};

// Damping 40 is 2 × √400: critically damped, so a card settles without wobble.
const SETTLE: Transition = { type: "spring", stiffness: 400, damping: 40, mass: 1 };
// Damping 30 is just over 2 × √200. A softer spring than SETTLE, so the card leaves at the finger's speed.
const FLY: Transition = { type: "spring", stiffness: 200, damping: 30, mass: 1 };
const FADE: Transition = { duration: 0.15 };
const FOLLOW: Transition = { duration: 0 };
// A release past this distance, or a flick faster than FLICK, dismisses the card.
const THRESHOLD = 96;
const FLICK = 600;
const FLICK_MIN_DISTANCE = 24;
const FLY_DISTANCE = 360;
// Degrees of tilt per pixel of travel: 8 degrees at the threshold.
const TILT = 8 / THRESHOLD;
const VISIBLE = 3;

interface Drag {
  id: number;
  startX: number;
  x: number;
  time: number;
  velocity: number;
}

interface DeckCardProps {
  cardKey: string;
  depth: number;
  leaving?: SwipeDirection;
  interactive: boolean;
  entering: boolean;
  reduceMotion: boolean;
  onRelease: (direction: SwipeDirection) => void;
  onGone: (key: string) => void;
  children: ReactNode;
}

function DeckCard({ cardKey, depth, leaving, interactive, entering, reduceMotion, onRelease, onGone, children }: DeckCardProps) {
  const ref = useRef<HTMLDivElement>(null);
  const drag = useRef<Drag | null>(null);
  const wasLeaving = useRef(false);
  // The speed the finger let go at, in pixels a second. A button press leaves it at zero.
  const releaseVelocity = useRef(0);

  // Painted straight onto the element, so a drag never re-renders the deck.
  const paint = (x: number, transition: Transition) => {
    if (ref.current) animate(ref.current, reduceMotion ? { x } : { x, rotate: x * TILT }, transition);
  };

  useEffect(() => {
    const node = ref.current;
    if (!node) return;
    if (!leaving) {
      // The parent kept this card after all, so it comes back to rest.
      if (wasLeaving.current) animate(node, { x: 0, rotate: 0, opacity: 1 }, reduceMotion ? FADE : SETTLE);
      wasLeaving.current = false;
      return;
    }
    wasLeaving.current = true;
    const side = leaving === "left" ? -1 : 1;
    const controls = reduceMotion
      ? animate(node, { opacity: 0 }, FADE)
      : animate(
          node,
          { x: side * FLY_DISTANCE, rotate: side * FLY_DISTANCE * TILT, opacity: 0 },
          // Only the travel inherits the finger's speed. A tilt or a fade at that speed would lurch.
          { default: FLY, x: { ...FLY, velocity: releaseVelocity.current } },
        );
    controls.then(() => onGone(cardKey));
    return () => controls.stop();
  }, [cardKey, leaving, onGone, reduceMotion]);

  const handleDown = (event: PointerEvent<HTMLDivElement>) => {
    if (!interactive || event.button !== 0 || drag.current) return;
    // Capture keeps the card under a finger that outruns it.
    event.currentTarget.setPointerCapture?.(event.pointerId);
    drag.current = { id: event.pointerId, startX: event.clientX, x: 0, time: event.timeStamp, velocity: 0 };
  };

  const handleMove = (event: PointerEvent<HTMLDivElement>) => {
    const state = drag.current;
    if (!state || state.id !== event.pointerId) return;
    const x = event.clientX - state.startX;
    const elapsed = event.timeStamp - state.time;
    if (elapsed > 0) state.velocity = ((x - state.x) / elapsed) * 1000;
    state.x = x;
    state.time = event.timeStamp;
    paint(x, FOLLOW);
  };

  const handleEnd = (event: PointerEvent<HTMLDivElement>) => {
    const state = drag.current;
    if (!state || state.id !== event.pointerId) return;
    drag.current = null;
    // A finger that stopped before lifting did not flick.
    const velocity = event.timeStamp - state.time > 100 ? 0 : state.velocity;
    const flicked =
      Math.abs(velocity) > FLICK && Math.abs(state.x) > FLICK_MIN_DISTANCE && Math.sign(velocity) === Math.sign(state.x);
    if (event.type === "pointerup" && (Math.abs(state.x) > THRESHOLD || flicked)) {
      releaseVelocity.current = velocity;
      onRelease(state.x < 0 ? "left" : "right");
      return;
    }
    // The spring starts at the finger's speed, so the card never stops dead before it returns.
    paint(0, reduceMotion ? FOLLOW : { x: { ...SETTLE, velocity }, rotate: { ...SETTLE, velocity: velocity * TILT } });
  };

  const rest = { scale: 1 - depth * 0.05, y: depth * 10, opacity: 1 };

  return (
    <motion.div
      // Only the top card is read out. The cards under it are a preview.
      aria-hidden={interactive ? undefined : true}
      initial={entering ? { ...rest, opacity: 0 } : false}
      animate={rest}
      transition={reduceMotion ? FOLLOW : SETTLE}
      // Positioned, so the cards stack in list order. A scaled card under an unscaled one would otherwise paint over it.
      className="relative col-start-1 row-start-1 origin-bottom"
    >
      <div
        ref={ref}
        data-swipe-card=""
        onPointerDown={handleDown}
        onPointerMove={handleMove}
        onPointerUp={handleEnd}
        onPointerCancel={handleEnd}
        className={cn(
          "overflow-hidden rounded-2xl border border-border bg-card text-foreground shadow-sm",
          interactive ? "cursor-grab touch-pan-y select-none active:cursor-grabbing" : "pointer-events-none",
        )}
      >
        {children}
      </div>
    </motion.div>
  );
}

function SkipGlyph() {
  return (
    <svg viewBox="0 0 16 16" fill="currentColor" aria-hidden="true" className="size-4">
      <path d="M4.7 3.3a1 1 0 0 0-1.4 1.4L6.6 8l-3.3 3.3a1 1 0 1 0 1.4 1.4L8 9.4l3.3 3.3a1 1 0 0 0 1.4-1.4L9.4 8l3.3-3.3a1 1 0 0 0-1.4-1.4L8 6.6 4.7 3.3Z" />
    </svg>
  );
}

function SaveGlyph() {
  return (
    <svg viewBox="0 0 16 16" fill="currentColor" aria-hidden="true" className="size-4">
      <path d="M4 2.5A1.5 1.5 0 0 1 5.5 1h5A1.5 1.5 0 0 1 12 2.5v11a.75.75 0 0 1-1.2.6L8 12l-2.8 2.1a.75.75 0 0 1-1.2-.6v-11Z" />
    </svg>
  );
}

const BUTTON =
  "inline-flex min-h-11 flex-1 cursor-pointer touch-manipulation items-center justify-center gap-2 rounded-full border px-4 text-sm font-medium outline-none active:scale-97 motion-safe:transition motion-safe:duration-150 focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background aria-disabled:cursor-not-allowed aria-disabled:opacity-50 aria-disabled:active:scale-100";

/**
 * A stack of cards to sort one at a time. The top card follows the finger and
 * tilts, then flies off past a threshold or springs back. The two buttons do
 * the same without a drag, so the deck never depends on a gesture.
 */
export function SwipeDeck<T>({
  label,
  items,
  getKey,
  getName,
  renderCard,
  index,
  defaultIndex = 0,
  onIndexChange,
  onSwipe,
  leftLabel = "Skip",
  rightLabel = "Save",
  emptyLabel = "No cards left",
  className,
  ...rootProps
}: SwipeDeckProps<T>) {
  const [ownIndex, setOwnIndex] = useState(defaultIndex);
  const [leaving, setLeaving] = useState<{ key: string; item: T; direction: SwipeDirection }[]>([]);
  // A card that joins the stack later fades in. The first cards are simply there.
  const [firstKeys] = useState(() => new Set(items.slice(0, (index ?? defaultIndex) + VISIBLE).map(getKey)));
  const reduceMotion = useReducedMotion() ?? false;
  const current = Math.min(Math.max(index ?? ownIndex, 0), items.length);
  const upcoming = items.slice(current, current + VISIBLE);
  const top = upcoming.at(0);
  const upcomingKeys = new Set(upcoming.map(getKey));

  const forget = useCallback((key: string) => setLeaving((list) => list.filter((entry) => entry.key !== key)), []);

  const dismiss = (direction: SwipeDirection) => {
    if (top === undefined) return;
    const key = getKey(top);
    setLeaving((list) => [...list.filter((entry) => entry.key !== key), { key, item: top, direction }]);
    if (index === undefined) setOwnIndex(current + 1);
    onIndexChange?.(current + 1);
    onSwipe?.(top, direction);
  };

  // Deepest first, so the top card paints last. A card on its way out stays
  // above them all until its flight ends.
  // One keyed list, so a dismissed card keeps its element and leaves from where the finger let go.
  const cards = [
    ...upcoming.map((item, depth) => ({ item, key: getKey(item), depth, ghost: false })).reverse(),
    ...leaving
      .filter((entry) => !upcomingKeys.has(entry.key))
      .map((entry) => ({ item: entry.item, key: entry.key, depth: 0, ghost: true })),
  ];

  return (
    <div {...rootProps} role="group" aria-label={label} className={cn("flex w-full max-w-xs flex-col gap-4", className)}>
      {/* The bottom padding holds the two cards that peek out under the top one, so they never reach the buttons. */}
      <div className="grid pb-5">
        {top === undefined ? (
          <p
            aria-hidden="true"
            className="col-start-1 row-start-1 grid min-h-32 place-items-center rounded-2xl border border-dashed border-border px-4 text-center text-sm text-muted-foreground"
          >
            {emptyLabel}
          </p>
        ) : null}
        {/* An unseen copy of the last card holds the deck's height, so the buttons stay put when the deck runs out. */}
        {top === undefined && items.length > 0 ? (
          <div aria-hidden="true" inert className="invisible col-start-1 row-start-1 overflow-hidden rounded-2xl border border-border">
            {renderCard(items[items.length - 1])}
          </div>
        ) : null}
        {cards.map(({ item, key, depth, ghost }) => (
          <DeckCard
            key={key}
            cardKey={key}
            depth={depth}
            leaving={leaving.find((entry) => entry.key === key)?.direction}
            interactive={depth === 0 && !ghost}
            entering={!firstKeys.has(key)}
            reduceMotion={reduceMotion}
            onRelease={dismiss}
            onGone={forget}
          >
            {renderCard(item)}
          </DeckCard>
        ))}
      </div>
      <p role="status" className="sr-only">
        {top === undefined ? emptyLabel : `${getName(top)}, ${current + 1} of ${items.length}`}
      </p>
      <div className="flex gap-3">
        <button
          type="button"
          // Not disabled when the deck runs out: a disabled button drops keyboard focus.
          aria-disabled={top === undefined || undefined}
          onClick={() => dismiss("left")}
          className={cn(BUTTON, "border-border bg-background text-foreground")}
        >
          <SkipGlyph />
          {leftLabel}
        </button>
        <button
          type="button"
          aria-disabled={top === undefined || undefined}
          onClick={() => dismiss("right")}
          className={cn(BUTTON, "border-primary bg-primary text-primary-foreground")}
        >
          <SaveGlyph />
          {rightLabel}
        </button>
      </div>
    </div>
  );
}
